  const state = {lang:localStorage.getItem('sisp_lang')||'en', data:null, activeTrack:null, activeLesson:null, searchResults:[], assistantMode:'ai', admin:null, adminData:null, adminSection:'dashboard', editingContent:null, editingTeam:null, createLesson:false, member:null, accountMode:'signup', aiHistory:[]};
  const main=document.getElementById('main'), csrfCookie=()=>state.data?.csrf_token||'';
