  const eye=(key)=>eyebrowText[state.lang]?.[key]||eyebrowText.en[key];
  const ageSuffix=()=>state.lang==='fr'?'ans':state.lang==='rw'?'imyaka':'years';
  const make=(tag,cls='',text='')=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined&&text!==null)n.textContent=text;return n;};
  const anchor=(href,label,page)=>{const a=make('a','',label);a.href=href;if(page)a.dataset.page=page;return a;};
  const btn=(label,cls='button button-primary',fn)=>{const b=make('button',cls,label);b.type='button';if(fn)b.addEventListener('click',fn);return b;};
  const currentProgress=()=>{if(state.member?.progress)return state.member.progress;try{return JSON.parse(localStorage.getItem('sisp_progress')||'{}')}catch{return {}}};
  const saveProgress=(slug)=>{const p=currentProgress();if(!p[slug]){p[slug]=true;if(state.member){state.member.progress=p;fetchJson('/api/account/progress',{method:'POST',body:JSON.stringify({progress:p})}).catch(()=>notice('Progress is saved on this device; account sync is unavailable.'));}else localStorage.setItem('sisp_progress',JSON.stringify(p));}};
  const allLessons=()=>state.data?.tracks.flatMap(track=>track.lessons.map(lesson=>lesson.slug))||[];
  function gamificationSummary(){const p=currentProgress(),completed=allLessons().filter(slug=>p[slug]).length,xp=completed*20,level=1+Math.floor(xp/100),badges=[];if(completed>=1)badges.push(state.lang==='fr'?'Premier pas':state.lang==='rw'?'Intambwe ya mbere':'First step');if(completed>=5)badges.push(state.lang==='fr'?'Parcours commencé':state.lang==='rw'?'Inzira yatangiye':'Pathfinder');if(completed>=15)badges.push(state.lang==='fr'?'Apprentissage régulier':state.lang==='rw'?'Umwigishwa uhamye':'Steady learner');if(completed>=30)badges.push(state.lang==='fr'?'Explorateur de sujets':state.lang==='rw'?'Umushakashatsi w’ingingo':'Topic explorer');return {completed,xp,level,badges};}
  function downloadCertificate(track){const p=currentProgress();if(!track.lessons.every(l=>p[l.slug]))return;const text=`Umucyo Spaces Hub\nPrivate learning completion\n\nPathway: ${track.title} (${track.ages})\nCompleted lessons: ${track.lessons.length}\n\nThis is a private record of learning activity on this device. It is not a professional qualification or proof of subject-matter competency.\n`;const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=make('a');a.href=url;a.download=`umucyo-learning-${track.id}.txt`;a.click();URL.revokeObjectURL(url);}
  const notice=(message)=>{const toast=document.getElementById('toast');toast.textContent=message;toast.hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>toast.hidden=true,2800);};
  async function fetchJson(url,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(['POST','PUT','DELETE'].includes((opts.method||'GET').toUpperCase()))headers['X-CSRF-Token']=csrfCookie();const response=await fetch(url,{...opts,headers,credentials:'same-origin'});let data={};try{data=await response.json()}catch{}if(!response.ok)throw Object.assign(new Error(data.error||'Request failed'),{status:response.status,data});return data;}
  async function loadData(){const res=await fetch(`/api/bootstrap?lang=${encodeURIComponent(state.lang)}`,{cache:'no-store'});state.data=await res.json();state.member=state.data.member||state.member;document.getElementById('review-notice').textContent=state.data.content_notice;document.getElementById('language').value=state.lang;document.documentElement.lang=state.lang;updateShellLabels();loadAiStatus();}
  async function loadAiStatus(){const node=document.getElementById('assistant-status');try{const response=await fetch(`/api/ai/status?lang=${encodeURIComponent(state.lang)}`,{cache:'no-store'});const data=await response.json();const copy={en:{ready:'Ready · answers use reviewed site content.',content_review_needed:'Waiting for reviewed and published content in this language.',not_configured:'AI provider keys are not configured yet.',unavailable:'Cyizere status is temporarily unavailable.'},rw:{ready:'Yiteguye · isubiza ikoresheje ibikubiyemo byasuzumwe.',content_review_needed:'Itegereje ibikubiyemo byasuzumwe kandi byasohotse muri uru rurimi.',not_configured:'Imfunguzo za AI ntizirashyirwaho.',unavailable:'Uko Cyizere ihagaze ntikuboneka ubu.'},fr:{ready:'Prêt · réponses fondées sur les contenus examinés du site.',content_review_needed:'En attente de contenus examinés et publiés dans cette langue.',not_configured:'Les clés du fournisseur IA ne sont pas encore configurées.',unavailable:'Le statut de Cyizere est temporairement indisponible.'}};node.textContent=(copy[state.lang]||copy.en)[data.status]||copy[state.lang].unavailable;node.dataset.state=data.status;}catch{node.textContent=state.lang==='fr'?'Le statut de Cyizere est temporairement indisponible.':state.lang==='rw'?'Uko Cyizere ihagaze ntikuboneka ubu.':'Cyizere status is temporarily unavailable.';}}
  function updateShellLabels(){document.querySelectorAll('.main-nav a[data-page],.footer-links a[data-page]').forEach(a=>{const key=a.dataset.page;if(translations[state.lang][key])a.textContent=translations[state.lang][key]});document.getElementById('admin-link').textContent=state.lang==='rw'?'Abakozi':state.lang==='fr'?'Équipe':'Staff sign-in';document.getElementById('utility-text').textContent=state.lang==='en'?'Your Health. Your Rights. Your Safe Space.':state.lang==='rw'?'Ubuzima bwawe. Uburenganzira bwawe. Ahantu hawe hatekanye.':'Votre santé. Vos droits. Votre espace sûr.';document.getElementById('urgent-link').textContent=state.lang==='en'?'Get help / Report violence':state.lang==='rw'?'Saba ubufasha / Imenyekanishe ihohoterwa':'Obtenir de l’aide / Signaler une violence';document.getElementById('review-learn-more').textContent=state.lang==='en'?'About our review process':state.lang==='rw'?'Uko dusuzuma ibikubiyemo':'Notre processus d’examen';document.getElementById('footer-location').textContent=t('location');document.getElementById('footer-tagline').textContent=state.lang==='en'?'Your Health. Your Rights. Your Safe Space.':state.lang==='rw'?'Ubuzima bwawe. Uburenganzira bwawe. Ahantu hawe hatekanye.':'Votre santé. Vos droits. Votre espace sûr.';const footerHelp=document.querySelector('.footer-links a[data-page=help]');if(footerHelp)footerHelp.textContent=t('getHelp');document.querySelector('.cyizere-launch small').textContent=state.lang==='en'?'Learning assistant':state.lang==='rw'?'Umufasha mu kwiga':'Assistant éducatif';document.querySelector('.menu-toggle .sr-only').textContent=state.lang==='fr'?'Ouvrir la navigation':state.lang==='rw'?'Fungura imiyoboro':'Open navigation';document.getElementById('footer-draft').textContent=t('reviewNote');document.getElementById('assistant-intro').textContent=t('assistantIntro');document.getElementById('assistant-title').textContent=state.lang==='fr'?'Bonjour, je suis Cyizere':state.lang==='rw'?'Muraho, ndi Cyizere':'Hello, I’m Cyizere';document.getElementById('assistant-mode-label').textContent=state.lang==='fr'?'ASSISTANT ÉDUCATIF IA':state.lang==='rw'?'UMUFASHA W’INYIGISHO WA AI':'AI EDUCATIONAL ASSISTANT';const modeLabels=state.lang==='fr'?['Chat IA','Texte humain','Soutien vocal']:state.lang==='rw'?['Ikiganiro na AI','Ubutumwa ku muntu','Ubufasha bw’amajwi']:['AI chat','Human text','Voice support'];document.querySelectorAll('.mode-tabs button').forEach((b,i)=>b.textContent=modeLabels[i]);document.getElementById('chat-privacy').textContent=state.lang==='fr'?'Si l’IA est activée, votre question et les derniers messages de cette conversation sont transmis au fournisseur configuré. Ses règles de confidentialité et de conservation s’appliquent. Le site ne conserve pas les transcriptions. N’indiquez ni nom, ni adresse, ni détail intime.':state.lang==='rw'?'AI ihujwe, ikibazo cyawe n’ubutumwa buheruka muri iki kiganiro byoherezwa ku itanga serivisi ryashyizweho. Amabwiriza yaryo yo kubika no kurinda amakuru arakurikizwa. Uru rubuga ntirubika inyandiko z’ibiganiro. Ntushyiremo izina, aderesi cyangwa amakuru y’ibanga.':'If AI is enabled, your question and recent chat messages are sent to the configured provider; that provider’s privacy and retention policies apply. The site does not store transcripts. Do not include a name, address or intimate detail.';document.getElementById('chat-input').placeholder=t('chatPlaceholder');document.querySelector('#chat-form button').textContent=t('send');}
  function appendTitle(container,eyebrow,title,lead){const head=make('div','page-heading');if(eyebrow)head.append(make('p','eyebrow',eyebrow));head.append(make('h1','',title));if(lead)head.append(make('p','',lead));container.append(head);return head;}
