  function trackCard(track){const b=make('button','track-card');b.type='button';b.setAttribute('aria-pressed',state.activeTrack===track.id?'true':'false');b.append(make('span','age-label',`${track.ages} ${ageSuffix()}`),make('h3','',track.title),make('p','',track.description));const p=currentProgress();const count=(track.lessons||[]).filter(l=>p[l.slug]).length;b.append(make('span','review-badge',`${count}/${track.lessons.length} ${t('progress')}`));b.addEventListener('click',()=>{state.activeTrack=track.id;state.activeLesson=null;render()});return b;}
