      form.addEventListener('submit',async e=>{e.preventDefault();feedback.hidden=true;try{const guestProgress=state.accountMode==='signup'?JSON.parse(localStorage.getItem('sisp_progress')||'{}'):{};const result=await fetchJson(state.accountMode==='signup'?'/api/account/register':'/api/account/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});state.member=result.member;if(state.accountMode==='signup'){if(Object.keys(guestProgress).length){const saved=await fetchJson('/api/account/progress',{method:'POST',body:JSON.stringify({progress:guestProgress})});state.member.progress=saved.progress}localStorage.removeItem('sisp_progress')}render()}catch(err){feedback.textContent=err.message;feedback.hidden=false}});card.append(form);
